from __future__ import annotations

import json
from pathlib import Path


def food(
    name: str,
    name_hindi: str,
    category: str,
    subcategory: str,
    calories: int,
    protein: float,
    carbs: float,
    fat: float,
    fiber: float,
    serving: str,
    serving_g: float,
    *,
    vegetarian: bool = True,
    vegan: bool | None = None,
    gluten_free: bool = False,
    allergens: list[str] | None = None,
    cost: int = 80,
) -> dict:
    if vegan is None:
        vegan = vegetarian
    return {
        "name": name,
        "name_hindi": name_hindi,
        "category": category,
        "subcategory": subcategory,
        "calories_per_100g": calories,
        "protein_per_100g": protein,
        "carbs_per_100g": carbs,
        "fat_per_100g": fat,
        "fiber_per_100g": fiber,
        "default_serving_description": serving,
        "default_serving_grams": serving_g,
        "is_vegetarian": vegetarian,
        "is_vegan": vegan,
        "is_gluten_free": gluten_free,
        "common_allergens": allergens or [],
        "approx_cost_per_kg_inr": cost,
    }


