def main() -> None:
    names = [i["name"] for i in ITEMS]
    if len(names) != len(set(names)):
        dupes = {n for n in names if names.count(n) > 1}
        raise ValueError(f"Duplicate food names: {dupes}")

    if len(ITEMS) < 200:
        raise ValueError(f"Expected 200+ items, got {len(ITEMS)}")

    out = Path(__file__).with_name("food_items.json")
    out.write_text(json.dumps(ITEMS, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"Wrote {len(ITEMS)} food items to {out}")


if __name__ == "__main__":
    main()
